import numpy as np
from scipy.optimize import least_squares
def fitm(f,npar,nstart=30):
    best=None; rng=np.random.default_rng(1)
    for s in range(nstart):
        p0=rng.normal(0,1,npar)
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda p: f(p)-sigma,p0,max_nfev=2000)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return np.mean(best.fun**2)/np.var(sigma), np.round(best.x,4)
F={
'pow_lin': lambda p: p[0]+p[1]*T+p[2]*T*T+(p[3]+p[4]*T)*np.abs(eps)**p[5]+p[6]*eps,
